import { DomainError } from "./domain-error";

export class OrderLine {
  constructor(
    readonly productId: string,
    readonly quantity: number,
  ) {
    if (productId.trim() === "") {
      throw new DomainError("VALIDATION", "Order line requires a product id");
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new DomainError("VALIDATION", "Order line quantity must be a positive integer");
    }
  }
}

export function mergeLines(lines: readonly OrderLine[]): OrderLine[] {
  const totals = new Map<string, number>();
  for (const line of lines) {
    totals.set(line.productId, (totals.get(line.productId) ?? 0) + line.quantity);
  }
  return [...totals].map(([productId, quantity]) => new OrderLine(productId, quantity));
}

